export default async function f(
  { scheduledAt, calendarId, pageToken, acknowledge, resolution },
  ctx,
) {
  if (acknowledge && !pageToken) {
    const s = await ctx.state.get(acknowledge);
    if (!s || s.status !== "pending" || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect exact pending approval request");
    s.status = resolution === "confirmed" ? "requested" : "absent";
    await ctx.state.set(acknowledge, s);
  }
  const d = Date.parse(scheduledAt),
    query = {
      timeMin: new Date(d - 4 * 86400000).toISOString(),
      timeMax: new Date(d - 2 * 86400000).toISOString(),
      singleEvents: true,
      maxResults: 2500,
    };
  if (pageToken) query.pageToken = pageToken;
  return { endpoint: "/calendars/" + encodeURIComponent(calendarId) + "/events", query };
}

