export default async function iterate({ page: response, previous }, ctx) {
  const items = response.items || [],
    nextPageToken = response.nextPageToken;
  const page = previous?.awaitPage
    ? { items, index: 0, nextPageToken: nextPageToken || "" }
    : (previous ?? { items, index: 0, nextPageToken: nextPageToken || "" });
  while (page.index < page.items.length) {
    const e = page.items[page.index++],
      id = e.id,
      contact = e.attendees?.find((a) => !a.self && a.email)?.email,
      start = e.start?.dateTime,
      end = e.end?.dateTime;
    if (
      !id ||
      !contact ||
      !start ||
      !end ||
      !Number.isFinite(Date.parse(start)) ||
      !Number.isFinite(Date.parse(end))
    )
      continue;
    const saved = await ctx.state.get("followup:" + id);
    if (saved && !["pending", "absent"].includes(saved.status)) continue;
    const duration = Date.parse(end) - Date.parse(start);
    if (duration <= 0) continue;
    const after = Math.floor(Date.parse(end) / 1000);
    return {
      state: page,
      hasEvent: true,
      morePages: false,
      pageToken: "",
      eventId: id,
      contact,
      event: JSON.stringify(e),
      query: `{from:${contact} to:${contact}} after:${after}`,
    };
  }
  return {
    state: { ...page, awaitPage: !!page.nextPageToken },
    hasEvent: false,
    morePages: !!page.nextPageToken,
    pageToken: page.nextPageToken || "",
    eventId: "",
    contact: "",
    event: "",
    query: "",
  };
}

