export default async function prepare({ eventId, event, contact, threads, calendarId }, ctx) {
  const key = "followup:" + eventId,
    e = JSON.parse(event),
    found = threads.length > 0;
  if (found) {
    await ctx.state.set(key, { status: "contacted" });
    return {
      followup: false,
      key,
      calendarId,
      items: [calendarId],
      timeMin: new Date().toISOString(),
      timeMax: new Date(Date.now() + 86400000).toISOString(),
      facts: "",
    };
  }
  const start = new Date(),
    end = new Date(start.getTime() + 14 * 86400000);
  return {
    followup: true,
    key,
    calendarId,
    items: [calendarId],
    timeMin: start.toISOString(),
    timeMax: end.toISOString(),
    facts: JSON.stringify({
      eventId,
      contact,
      summary: e.summary || "",
      start: e.start,
      end: e.end,
    }),
  };
}

