export default async function reserve(
  { key, event, contact, slots, calendars, calendarId, acknowledge, resolution },
  ctx,
) {
  let s = await ctx.state.get(key);
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect approval request " + key);
    if (resolution === "confirmed") {
      s.status = "requested";
      await ctx.state.set(key, s);
      return { send: false, subject: "", message: "" };
    }
  }
  if (s?.status === "requested" || s?.status === "done")
    return { send: false, subject: "", message: "" };
  const c = calendars[calendarId];
  if (!c?.isReliable || !Array.isArray(c.free)) throw Error("Unavailable calendar data");
  if (!Array.isArray(slots.slots)) throw Error("Invalid suggested slots");
  const original = JSON.parse(event),
    zone = original.start?.timeZone || "UTC",
    weekday = (t) =>
      !["Sat", "Sun"].includes(
        new Intl.DateTimeFormat("en-US", { weekday: "short", timeZone: zone }).format(new Date(t)),
      );
  const valid = slots.slots.filter(
    (v) =>
      Number.isFinite(Date.parse(v.start)) &&
      Number.isFinite(Date.parse(v.end)) &&
      Date.parse(v.end) > Date.parse(v.start) &&
      Date.parse(v.start) > Date.now() &&
      weekday(v.start) &&
      c.free.some(
        (f) => Date.parse(v.start) >= Date.parse(f.start) && Date.parse(v.end) <= Date.parse(f.end),
      ),
  );
  if (!valid.length) throw Error("No valid future free slots");
  s = { status: "pending", event: original, contact, slots: valid };
  await ctx.state.set(key, s);
  const eid = key.slice("followup:".length);
  return {
    send: true,
    subject: "Book a follow-up with " + contact + "?",
    message:
      "Event ID: " +
      eid +
      '\n\nPlease choose a follow-up time or dismiss, then POST { "eventId": "' +
      eid +
      '", "text": "..." } to your callback webhook:\n' +
      valid.map((v) => v.start + " to " + v.end).join("\n"),
  };
}

