export default async function f({ key, messageId }, ctx) {
  if (!messageId) throw Error("Unknown email result");
  const s = await ctx.state.get(key);
  if (!s) throw Error("Missing request");
  if (["booking", "done", "requested"].includes(s.status)) return { ok: true };
  if (s.status !== "pending") throw Error("Unexpected request state");
  s.status = "requested";
  await ctx.state.set(key, s);
  return { ok: true };
}

