export default async function decision({ body, calendarId, acknowledge, resolution }, ctx) {
  const key = "followup:" + String(body.eventId || ""),
    s = await ctx.state.get(key);
  if (!s || !["pending", "requested", "booking", "done"].includes(s.status))
    throw Error("Unknown follow-up");
  if (s.status === "done")
    return {
      write: false,
      key,
      event: {
        summary: "unused",
        start: { dateTime: "2000-01-01T00:00:00Z" },
        end: { dateTime: "2000-01-01T01:00:00Z" },
      },
      calendarId,
    };
  if (s.status === "booking") {
    if (acknowledge !== key + ":booking" || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect calendar before retry " + key + ":booking");
    if (resolution === "confirmed") {
      s.status = "done";
      await ctx.state.set(key, s);
      return {
        write: false,
        key,
        event: {
          summary: "unused",
          start: { dateTime: "2000-01-01T00:00:00Z" },
          end: { dateTime: "2000-01-01T01:00:00Z" },
        },
        calendarId,
      };
    }
  }
  if (body.choice === "dismiss") {
    s.status = "done";
    await ctx.state.set(key, s);
    return {
      write: false,
      key,
      event: {
        summary: "unused",
        start: { dateTime: "2000-01-01T00:00:00Z" },
        end: { dateTime: "2000-01-01T01:00:00Z" },
      },
      calendarId,
    };
  }
  const start = String(body.start || ""),
    end = String(body.end || "");
  if (
    !Number.isFinite(Date.parse(start)) ||
    !Number.isFinite(Date.parse(end)) ||
    Date.parse(start) <= Date.now() ||
    Date.parse(end) <= Date.parse(start)
  )
    throw Error("Human decision must specify a future time");
  s.status = "booking";
  await ctx.state.set(key, s);
  return {
    write: true,
    key,
    calendarId,
    event: {
      summary: "Follow-up: " + (s.event.summary || "Meeting"),
      description: "Follow-up with " + s.contact,
      start: { dateTime: start },
      end: { dateTime: end },
    },
  };
}

